function queryNetList(){var n=getUrlParameter("fundId"),t=getUrlParameter("isSub");$.ajax({async:!0,url:"/WeixinService/business/queryEstimateByFundId.xhtml",data:{fundId:n},dataType:"json",type:"POST",cache:!1,error:function(){show_tips("网络繁忙，请稍后再试。")},success:function(n){var r=n.productEstimateList,t="",i;r!=null&&r.length>0&&(i="",$.each(r,function(n,r){i=r.fluctuate>=0?"<span class='red'>"+parseFloat(numMulti(r.fluctuate,100)).toFixed(2)+"%<\/span>":"<span class='green'>"+parseFloat(numMulti(r.fluctuate,100)).toFixed(2)+"%<\/span>";t+="<li>";t+="<span>"+formatDate(r.eDate)+"<\/span>";t+="<span>"+parseFloat(r.netValue).toFixed(4)+"<\/span>";t+="<span>"+parseFloat(r.accNetValue).toFixed(4)+"<\/span>";t+=i;t+="<\/li>"}),$(".historyNetworthCon ul").html(t))}})}$(document).ready(function(){queryNetList()})